package dev.aura.player;
import static org.junit.Assert.*;import org.junit.*;import org.junit.runner.RunWith;import androidx.test.ext.junit.runners.AndroidJUnit4;import androidx.test.platform.app.InstrumentationRegistry;import androidx.media3.session.MediaController;
import android.content.*;import android.graphics.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
@RunWith(AndroidJUnit4.class)
@androidx.annotation.OptIn(markerClass=androidx.media3.common.util.UnstableApi.class)
public class LowCostUiTest {
 final android.app.Instrumentation inst=InstrumentationRegistry.getInstrumentation();final Context c=inst.getTargetContext();MainActivity activity;Object savedBudget;boolean savedScan;
 @Before public void setup()throws Exception{savedScan=c.getSharedPreferences("aura",0).getBoolean("scanOnLaunch",false);c.getSharedPreferences("aura",0).edit().putBoolean("scanOnLaunch",false).commit();var cache=PlaybackBudget.class.getDeclaredField("cached");cache.setAccessible(true);savedBudget=cache.get(null);cache.set(null,PlaybackBudget.choose(28,128,false,2L<<30));AudioSettings.init(c);AudioSettings.put("mode","android");AudioSettings.put("perfect",false);AudioSettings.put("eq",false);activity=(MainActivity)inst.startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));await(()->main(()->get("player")!=null&&!(Boolean)get("libraryLoading")),10000);}
 @After public void cleanup()throws Exception{main(()->{player().stop();player().clearMediaItems();activity.finish();return null;});var cache=PlaybackBudget.class.getDeclaredField("cached");cache.setAccessible(true);cache.set(null,savedBudget);ArtworkView.clearCache();c.getSharedPreferences("aura",0).edit().putBoolean("scanOnLaunch",savedScan).commit();}
 @Test public void longLyricsRestyleOnlyPreviousAndCurrentLines()throws Exception{main(()->{var lines=new ArrayList<Lrc.Line>();var views=(List<TextView>)get("lyricViews");views.clear();for(int i=0;i<1500;i++){lines.add(new Lrc.Line(i*1000L,"Line "+i,List.of()));views.add(new CountText(activity));}set("lyricLines",lines);set("lyricTimings",List.of());set("page","lyrics");set("activeLine",700);set("lyricsManualUntil",Long.MAX_VALUE);CountText.changes=0;var update=MainActivity.class.getDeclaredMethod("updateLyrics",long.class);update.setAccessible(true);update.invoke(activity,701100L);assertEquals(2,CountText.changes);CountText.changes=0;update.invoke(activity,701200L);assertEquals(0,CountText.changes);return null;});}
 @Test public void lyricTouchExcludesPaddingTrailingSpaceAndWordGaps()throws Exception{int[] clicks={0};KaraokeLineView text=main(()->{KaraokeLineView v=new KaraokeLineView(activity);v.setText("Hello     world");v.setTextSize(24);v.setPadding(12,36,12,36);v.measure(View.MeasureSpec.makeMeasureSpec(700,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(200,View.MeasureSpec.AT_MOST));v.layout(0,0,v.getMeasuredWidth(),v.getMeasuredHeight());Ui.tap(v,()->clicks[0]++);FrameLayout host=new FrameLayout(activity);activity.setContentView(host);host.addView(v,new FrameLayout.LayoutParams(700,-2));return v;});main(()->{var layout=text.getLayout();float y=text.getExtendedPaddingTop()+layout.getLineBaseline(0)-10,x=text.getCompoundPaddingLeft()+layout.getPrimaryHorizontal(1);assertTrue(text.hitsText(x,y));tap(text,x,y);return null;});inst.waitForIdleSync();assertEquals(1,clicks[0]);main(()->{var layout=text.getLayout();float y=text.getExtendedPaddingTop()+layout.getLineBaseline(0)-10,x=text.getCompoundPaddingLeft()+layout.getPrimaryHorizontal(1);tap(text,600,y);tap(text,x,3);float gap=text.getCompoundPaddingLeft()+(layout.getPrimaryHorizontal(7)+layout.getPrimaryHorizontal(8))/2;assertFalse(text.hitsText(gap,y));tap(text,gap,y);return null;});inst.waitForIdleSync();assertEquals(1,clicks[0]);}
 @Test public void mixedFolderRowsReuseTheirOwnViewType()throws Exception{var songs=new ArrayList<Track>();for(int i=0;i<40;i++){songs.add(new Track("content://perf/f"+i,"Nested "+i,"Artist","Album","Music",1000,"").withPath(List.of(new FolderTree.Part("root","Music"),new FolderTree.Part("f"+i,"Folder "+i))));songs.add(new Track("content://perf/s"+i,"Song "+i,"Artist","Album","Music",1000,"").withPath(List.of(new FolderTree.Part("root","Music"))));}main(()->{set("tracks",songs);set("tab","폴더");set("source","local");set("folderCursor","local/root");go("library");return null;});await(()->main(()->get("activeList")!=null&&((androidx.recyclerview.widget.RecyclerView)get("activeList")).getAdapter().getItemCount()==80),5000);main(()->{var list=(androidx.recyclerview.widget.RecyclerView)get("activeList");androidx.recyclerview.widget.RecyclerView.Adapter adapter=list.getAdapter();assertNotEquals(adapter.getItemViewType(0),adapter.getItemViewType(40));for(int start:new int[]{0,40}){var holder=adapter.createViewHolder(list,adapter.getItemViewType(start));adapter.bindViewHolder(holder,start);View first=((ViewGroup)holder.itemView).getChildAt(0);adapter.bindViewHolder(holder,start+1);assertSame(first,((ViewGroup)holder.itemView).getChildAt(0));}return null;});}
 @Test public void notificationUsesTransparentAuraGlyphAndPlaybackKeepsIt()throws Exception{var icon=c.getDrawable(R.drawable.ic_stat_aura);Bitmap bitmap=Bitmap.createBitmap(48,48,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,48,48);icon.draw(new Canvas(bitmap));assertEquals(0,Color.alpha(bitmap.getPixel(0,0)));assertTrue(Color.alpha(bitmap.getPixel(24,24))>0);bitmap.recycle();File tone=new File(c.getCacheDir(),"perf-notification.wav");try(var in=inst.getContext().getAssets().open("tone.wav");var out=new FileOutputStream(tone)){out.write(Io.read(in));}main(()->{Track track=new Track(Uri.fromFile(tone).toString(),"Notification check","AURA","", "",3000,"");set("tracks",new ArrayList<>(List.of(track)));player().setMediaItem(track.item());player().setRepeatMode(androidx.media3.common.Player.REPEAT_MODE_ONE);player().prepare();player().play();return null;});await(()->{for(var n:c.getSystemService(android.app.NotificationManager.class).getActiveNotifications())if(n.getNotification().getSmallIcon()!=null&&n.getNotification().getSmallIcon().getResId()==R.drawable.ic_stat_aura)return true;return false;},8000);main(()->{go("lyrics");assertNotNull(((View)get("lyricsChrome")).findViewWithTag("lyricsPosition"));return null;});await(()->main(()->(Boolean)get("lyricsFramesRunning")),5000);main(()->{inst.callActivityOnStop(activity);assertFalse((Boolean)get("lyricsFramesRunning"));inst.callActivityOnStart(activity);return null;});}
 @Test public void outputListHidesInternalDuplicatesWithoutMergingIdenticalNames(){var p=List.of(new OutputDevices.Port(1,1,"SM-S931N",""),new OutputDevices.Port(2,2,"SM-S931N",""),new OutputDevices.Port(3,24,"SM-S931N",""),new OutputDevices.Port(4,8,"Headphones","AA:BB"),new OutputDevices.Port(5,7,"Headphones","aa:bb"),new OutputDevices.Port(6,11,"DAC","card=1"),new OutputDevices.Port(7,11,"DAC","card=2"));var visible=OutputDevices.music(p,0);assertEquals(List.of(2,4,6,7),visible.stream().map(OutputDevices.Port::id).collect(java.util.stream.Collectors.toList()));assertEquals(5,OutputDevices.music(p,5).get(1).id());assertEquals(2,OutputDevices.music(List.of(new OutputDevices.Port(8,11,"DAC",""),new OutputDevices.Port(9,11,"DAC","")),0).size());}
 @Test public void trackNumbersSurviveStorageAndSortNumerically()throws Exception{Track ten=new Track("content://sort/10","A","Artist","Album","",1000,"").withNumbers(10,1),two=new Track("content://sort/2","Z","Artist","Album","",3000,"").withNumbers(2,1),disc=new Track("content://sort/disc","B","Artist","Album","",2000,"").withNumbers(1,2),unknown=new Track("content://sort/no","C","Artist","Album","",4000,"");assertEquals(2,TrackOrder.number("02/12"));assertEquals(0,TrackOrder.number("invalid"));Track round=Track.from(two.withPath(List.of(new FolderTree.Part("r","Music"))).json());assertEquals(2,round.trackNumber);assertEquals(1,round.discNumber);assertEquals(Integer.valueOf(2),round.item().mediaMetadata.trackNumber);var input=List.of(ten,unknown,disc,two);assertEquals(List.of(two,ten,disc,unknown),TrackOrder.sorted(input,"track",false));assertEquals(List.of(disc,ten,two,unknown),TrackOrder.sorted(input,"track",true));assertEquals(List.of(ten,disc,unknown,two),TrackOrder.sorted(input,"title",false));assertEquals(input,TrackOrder.sorted(input,"stored",false));var result=LibraryQuery.run(input,"all","","앨범","track",false);assertEquals(two,result.groups.values().iterator().next().get(0));}
 @Test public void localReaderExtractsTrackAndDiscFromRealFlac()throws Exception{File file=new File(c.getCacheDir(),"numbered.flac");try(var in=inst.getContext().getAssets().open("numbered.flac");var out=new FileOutputStream(file)){out.write(Io.read(in));}Class<?> entry=Class.forName("dev.aura.player.Library$Entry");var ctor=entry.getDeclaredConstructors()[0];ctor.setAccessible(true);Object row=ctor.newInstance(Uri.fromFile(file),file.getName(),"Music","",file.length(),0L,"numbered",List.of());var read=Library.class.getDeclaredMethod("read",entry);read.setAccessible(true);Track track=(Track)read.invoke(new Library(c),row);assertEquals("Tagged track",track.title);assertEquals(2,track.trackNumber);assertEquals(2,track.discNumber);}
 @Test public void lyricsProgressScrubsAndStaysVisibleWhileHeld()throws Exception{File tone=new File(c.getCacheDir(),"lyrics-seek.wav");try(var in=inst.getContext().getAssets().open("tone.wav");var out=new FileOutputStream(tone)){out.write(Io.read(in));}main(()->{Track track=new Track(Uri.fromFile(tone).toString(),"Progress","AURA","","",3000,"");set("tracks",new ArrayList<>(List.of(track)));player().setMediaItem(track.item());player().prepare();return null;});await(()->main(()->player().getDuration()>2000),5000);main(()->{go("lyrics");return null;});inst.waitForIdleSync();SeekBar bar=main(()->(SeekBar)((View)get("lyricsChrome")).findViewWithTag("lyricsPosition"));assertNotNull(bar);long now=SystemClock.uptimeMillis();main(()->{var down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,bar.getWidth()*.6f,bar.getHeight()/2f,0);bar.dispatchTouchEvent(down);down.recycle();return null;});Thread.sleep(3300);assertEquals(View.VISIBLE,main(()->((View)get("lyricsChrome")).getVisibility()).intValue());main(()->{var up=MotionEvent.obtain(now,SystemClock.uptimeMillis(),MotionEvent.ACTION_UP,bar.getWidth()*.7f,bar.getHeight()/2f,0);bar.dispatchTouchEvent(up);up.recycle();return null;});await(()->main(()->player().getCurrentPosition()>1500),3000);}
 static class CountText extends TextView{static int changes;CountText(Context c){super(c);}@Override public void setTextColor(int color){super.setTextColor(color);changes++;}}
 void tap(View v,float x,float y){long now=SystemClock.uptimeMillis();var down=MotionEvent.obtain(now,now,MotionEvent.ACTION_DOWN,x,y,0);var up=MotionEvent.obtain(now,now+50,MotionEvent.ACTION_UP,x,y,0);v.dispatchTouchEvent(down);v.dispatchTouchEvent(up);down.recycle();up.recycle();}
 void go(String page)throws Exception{var m=MainActivity.class.getDeclaredMethod("go",String.class);m.setAccessible(true);m.invoke(activity,page);}MediaController player()throws Exception{return (MediaController)get("player");}Object get(String key)throws Exception{var f=MainActivity.class.getDeclaredField(key);f.setAccessible(true);return f.get(activity);}void set(String key,Object value)throws Exception{var f=MainActivity.class.getDeclaredField(key);f.setAccessible(true);f.set(activity,value);} <T>T main(Callable<T> action)throws Exception{FutureTask<T> task=new FutureTask<>(action);inst.runOnMainSync(task);return task.get(20,TimeUnit.SECONDS);}void await(Callable<Boolean> condition,long timeout)throws Exception{long end=SystemClock.elapsedRealtime()+timeout;while(!condition.call()&&SystemClock.elapsedRealtime()<end)Thread.sleep(50);assertTrue(condition.call());}
}
